def parse_run_line(text):
    """-> {field: value string} for the fields of FIELD_RE that the first line carries (tolerant: a missing field is simply absent)"""
    ln = first_line(text)
    out = {}
    for k, rx in FIELD_RE.items():
        m = re.search(r"(?:^|\s)" + rx + r"(?=\s|$)", ln)
        if m:
            out[k] = m.group(1)
    return out


def _same(x, y):
    if str(x).lower() == str(y).lower():
        return True
    try:
        return abs(float(x) - float(y)) <= 1e-12
    except ValueError:
        return False


def d2_line_failures(new, ref):
    """note N1 on two parsed lines: every field both carry is equal; form, replan steps, rule every, readout, kappa, model seed and reader seed are present in both; where the reference carries no pre-roll
    the new line reads `preroll 0`, no grid the new line reads `grid eval_grid_windows.json`, no nav the new line reads `nav deadreckon`. A field the reference carries and the new line lacks is not a failure of its own."""
    bad = []
    for k in D2_REQUIRED:
        if k not in new:
            bad.append("the new line carries no %s" % k)
        if k not in ref:
            bad.append("the reference line carries no %s" % k)
    for k in D2_COMPARED:
        if k in new and k in ref and not _same(new[k], ref[k]):
            bad.append("%s: new %s, reference %s" % (k, new[k], ref[k]))
    for k, dflt in D2_DEFAULTS:
        if k not in ref and not (k in new and _same(new[k], dflt)):
            bad.append("the reference line carries no %s, the new line has to read %s %s (it reads %s)" % (k, k, dflt, new.get(k)))
    return bad


# ============================================================================================ rule logs
def load_logs_setting(pull, run, m, S):
    """the rule logs of a run at setting S. Both settings use --rule-every 5, so both logs (rule_log and rule_log_mid) are needed, by the model reader's own load_logs. With no --rule-every a run writes the first
    log only; then the first log is needed and a mid log is read only if it lies on disk (kept from the reader of card ADD113)."""
    if SPEC[S]["every"] is not None:
        return MD.load_logs(pull, run, m)
    d = os.path.join(pull, "I10%s_s%d" % (run, m), "ticks")
    first = os.path.join(d, "rule_log_I10%s_s%d.npz" % (run, m))
    mid = os.path.join(d, "rule_log_mid_I10%s_s%d.npz" % (run, m))
    if not os.path.isfile(first):
        raise SystemExit("REFUSED: no rule log %s" % first)
    zs = []
    for p in [first] + ([mid] if os.path.isfile(mid) else []):
        with np.load(p, allow_pickle=False) as z:
            zs.append({k: z[k] for k in z.files})
    return zs


def rows4(logs):
    """-> (ci, j, present, g_src) over the logs of one rollout; tolerant of a log with no c_src column (the label form need not log a closing input)"""
    cols = {k: [] for k in ("ci", "j", "present", "g_src")}
    for z in logs:
        for k in cols:
            cols[k].append(np.asarray(z[k]))
    return (np.concatenate(cols["ci"]).astype(np.int64), np.concatenate(cols["j"]).astype(np.int64), np.concatenate(cols["present"]).astype(bool),
            np.concatenate(cols["g_src"]).astype(np.float64))


