def gap_file_of(a, arm):
    return (getattr(a, "gap_files", None) or {}).get(NEW_FILES[arm])


def parse_gap_files(items):
    """--gap-file NAME=PATH (repeated) -> {NAME: PATH}; NAME is VGAPJE or VGAPJE90"""
    out = {}
    for it in items or []:
        nm, sep, p = str(it).partition("=")
        if not sep or not p or nm not in NEW_FILES.values() or nm in out:
            raise SystemExit("REFUSED: --gap-file takes NAME=PATH once for each NAME of %s, got %r" % (sorted(NEW_FILES.values()), it))
        out[nm] = p
    return out


def rule_checks(a):
    """-> per-rollout dict (key S_arm_s<m>) of the rule-log checks of the six new rollouts: the model reader's w2_one against the joined gap file of the arm (VGAPJE for the JEc runs, VGAPJE90 for the JA90
    runs): the gap the rule received at steps with an output equals the file's gap within 1e-3 m; the gap the reader itself logs, for the lead steps where the file has no output, comes from the rule log of the
    reference run RR of the setting at the same model seed; the rule log meta names the hash of its gap file and the closing switch."""
    per = {}
    for S, arm in new_pairs():
        gf = gap_file_of(a, arm)
        for m in SEEDS:
            key = "%s_%s_s%d" % (S, arm, m)
            try:
                if not gf or not os.path.isfile(gf):
                    per[key] = {"PASS": False, "failures": ["no gap file %s for %s" % (gf, NEW_FILES[arm])]}
                    continue
                gref = MD.gapfile_ref(gf)
                fsha = sha_file(gf)
                logs = load_logs_setting(a.pull, run_name(S, arm), m, S)
                ref_logs = load_logs_setting(a.pull, run_name(S, "RR"), m, S)
                v0 = MD.lead_multi(MD.rows_of(ref_logs))
                meta = MD.meta_of(logs[0])
                r = MD.w2_one(MD.rows_of(logs), gref, v0, meta_expect={"vis_closing": 1}, meta=meta)
                ms = str(meta.get("vis_gap_file_sha256") or "").lower()
                if not (len(ms) >= 16 and (fsha.startswith(ms) or ms.startswith(fsha))):
                    r["failures"] = list(r.get("failures", [])) + ["rule log meta names the gap file hash %s, the file %s on disk has %s" % (ms[:16] or None, NEW_FILES[arm], fsha[:16])]
                    r["PASS"] = False
                per[key] = r
            except (SystemExit, OSError, ValueError, KeyError) as ex:
                per[key] = {"PASS": False, "failures": ["cannot read the rollout, its reference or its gap file: %s: %s" % (type(ex).__name__, ex)]}
    return per


def _hash_match(x, y):
    x, y = str(x or "").lower(), str(y or "").lower()
    return len(x) >= 16 and len(y) >= 16 and (x.startswith(y) or y.startswith(x))


def ctl_j01234(rec, shas):
    """j0 to j4 (card section 5) read from the record of the gap files BOXFUSE10K_GAPFILES_RECORD.json: each of j0 to j4 passes when the record has pass_j<k> true (JSON true).
    j0 also needs the record's card to be PREREG_V8F_PROOF_ADD131. j1 also needs the sha256 of each of the two gap files on disk (shas {VGAPJE: sha256, VGAPJE90: sha256}) to equal the record's
    files[<name>].sha256. -> {j0: {pass, failures}, ..., j4: {...}}"""
    rec = rec if isinstance(rec, dict) else {}
    bad = {"j%d" % i: [] for i in range(5)}
    for i in range(5):
        v = rec.get("pass_j%d" % i)
        if v is not True:
            bad["j%d" % i].append("the record of the gap files has pass_j%d %s" % (i, v))
    if rec.get("card") != CARD:
        bad["j0"].append("the record of the gap files names the card %r, not %s" % (rec.get("card"), CARD))
    for nm in sorted(NEW_FILES.values()):
        want = ((rec.get("files") or {}).get(nm) or {}).get("sha256")
        got = (shas or {}).get(nm)
        if not got or not want or str(got).lower() != str(want).lower():
            bad["j1"].append("%s on disk has sha256 %s, the record holds %s" % (nm, (got or "none")[:16], str(want or "none")[:16]))
    return {k: {"pass": not v, "failures": v} for k, v in bad.items()}


def ctl_e1(wrapper_sha16, check_text, hashes_text, check_files_present, run_shas):
    """e1 wrapper: the wrapper file has the hash 28bc31f21ecb4ccb; the banked check files are in place, the pod check record ends with `ZZ CHECK-WRAPPER-V PASS` and the hashes name the wrapper; the run text of each of
    the six new runs names a wrapper hash that begins with it"""
    bad = []
    if wrapper_sha16 != WRAPPER_SHA:
        bad.append("the wrapper file is %s, not %s" % (wrapper_sha16, WRAPPER_SHA))
    if not check_files_present:
        bad.append("a banked check file of the wrapper is missing")
    if last_line(check_text).strip() != CHECK_LAST:
        bad.append("the last line of the pod check is %r" % last_line(check_text).strip())
    if WRAPPER_SHA not in (hashes_text or ""):
        bad.append("the pod check hashes do not name %s" % WRAPPER_SHA)
    for k in new_keys():
        v = run_shas.get(k)
        if v is None:
            bad.append("%s: the run text names no wrapper hash" % k)
        elif not v.startswith(WRAPPER_SHA):
            bad.append("%s: the run text names the wrapper hash %s" % (k, v[:16]))
    return {"pass": not bad, "failures": bad, "wrapper_sha16": wrapper_sha16}


