def ctl_e2(lines, rc):
    """e2 arguments: lines {key: (new text, reference text)} for the six new runs; the clause of note N1 per run (d2_line_failures) and the rule log shows the rule acting on steps with a lead (a share above 0).
    The q-map file of each new run being the one of its reference run is read by the lead from the printed commands of the dry run and logged before the queue start: it is not coded here."""
    bad = []
    if sorted(lines) != sorted(new_keys()):
        bad.append("run lines read: %s, expected %s" % (sorted(lines), sorted(new_keys())))
    for k, (tn, tr) in sorted(lines.items()):
        if not first_line(tn):
            bad.append("%s: no run log of the new run" % k)
            continue
        if not first_line(tr):
            bad.append("%s: no run log of the reference run" % k)
            continue
        bad += ["%s: %s" % (k, x) for x in d2_line_failures(parse_run_line(tn), parse_run_line(tr))]
        sh = (rc.get(k) or {}).get("share_of_rule_steps_with_a_lead")
        if not (sh is not None and sh > 0):
            bad.append("%s: the rule log shows no rule step with a lead (share %s)" % (k, sh))
    return {"pass": not bad, "failures": bad}


def ctl_j6(levels):
    """j6 identity of the banked cells: the reader reproduces within 1e-4 the banked levels (C, U, F) of every cell of EXPECTED, read by the same code path as the new cells. levels {S: {arm: {C,U,F}}}.
    The failure text names the cell and the measure and holds no value."""
    bad = []
    for S, arms in EXPECTED.items():
        for arm, want in arms.items():
            for c, v in zip("CUF", want):
                got = (((levels or {}).get(S) or {}).get(arm) or {}).get(c)
                if got is None or not np.isfinite(got):
                    bad.append("%s %s %s: no level read" % (S, arm, c))
                elif abs(float(got) - v) > LEVEL_TOL + 1e-12:
                    bad.append("%s %s %s: not within the tolerance of the banked level" % (S, arm, c))
    return {"pass": not bad, "failures": bad}


def _pytest_ok(text, nm):
    bad = []
    hits = re.findall(r"(\d+) passed", text or "")
    if not (hits and int(hits[-1]) > 0):
        bad.append("%s: no line with a count of passed tests above 0" % nm)
    if re.search(r"\b\d+ (failed|errors?)\b", text or ""):
        bad.append("%s: the test output has a failed or error count" % nm)
    return bad


def ctl_e4(text_queue, text_read, mtime_queue, mtime_read, queue_start, controls_start):
    """e4 tests: the output of the queue kit's test (written by the lead outside the kit folders) and that of this kit's test each carry `N passed` and no failed or error count; the first is not later than the first
    start epoch of the queue, the second not later than the start of the controls stage"""
    bad = _pytest_ok(text_queue, "queue kit") + _pytest_ok(text_read, "reader kit")
    mq, mr, qs, cs = to_epoch(mtime_queue), to_epoch(mtime_read), to_epoch(queue_start), to_epoch(controls_start)
    if mq is None or mr is None or qs is None or cs is None:
        bad.append("a time is missing (queue test %s, reader test %s, queue start %s, controls start %s)" % (mtime_queue, mtime_read, queue_start, controls_start))
    else:
        if not mq <= qs:
            bad.append("the queue kit's test output (%s) is later than the first start epoch of the queue (%s)" % (mq, qs))
        if not mr <= cs:
            bad.append("the reader kit's test output (%s) is later than the start of the controls stage (%s)" % (mr, cs))
    return {"pass": not bad, "failures": bad}


def ctl_e5(per_setting):
    """e5 engine: for each of the two settings the engine's own controls of the grid read and of the strategic grid pass (as control g8 of the model reader)"""
    bad, det = [], {}
    if sorted(per_setting) != sorted(SETTINGS):
        bad.append("settings read: %s, expected %s" % (sorted(per_setting), sorted(SETTINGS)))
    for S, v in sorted(per_setting.items()):
        r = MD.ctl_g8(v.get("grid_all_pass"), v.get("strategic_a"), v.get("strategic_b"))
        det[S] = {"grid_all_pass": v.get("grid_all_pass"), "strategic_stage_A_pass": v.get("strategic_a"), "strategic_stage_B_pass": v.get("strategic_b")}
        if not r["PASS"]:
            bad.append("%s: grid_all_pass %s, strategic stage A %s, stage B %s%s" % (S, v.get("grid_all_pass"), v.get("strategic_a"), v.get("strategic_b"),
                                                                                    (" (" + v["strategic_reason"] + ")") if v.get("strategic_reason") else ""))
    return {"pass": not bad, "failures": bad, "per_setting": det}


def ctl_e6(done, n_dumps, expect, done_marker_text=None):
    """e6 counts: every new run has its done marker and 141 dump files (`expect`). done {key: bool}, n_dumps {key: int}"""
    bad = []
    for k in new_keys():
        if done.get(k) is not True:
            bad.append("%s: no T1_DONE" % k)
        if n_dumps.get(k) != expect:
            bad.append("%s: %s dump files, %s expected" % (k, n_dumps.get(k), expect))
    if done_marker_text is not None and not DONE_RE.match(last_line(done_marker_text).strip()):
        bad.append("the queue done marker reads %r" % last_line(done_marker_text)[:100])
    return {"pass": not bad, "failures": bad, "values": {"dump_files": n_dumps, "expected": expect}}


def ctl_e7(per):
    """rule logs (part of j9): each new run against its own joined gap file (rule_checks)"""
    bad = []
    if sorted(per) != sorted(new_keys()):
        bad.append("rollouts read: %s, expected %s" % (sorted(per), sorted(new_keys())))
    for k, v in sorted(per.items()):
        bad += ["%s: %s" % (k, x) for x in v.get("failures", [])]
        if v.get("PASS") is not True and not v.get("failures"):
            bad.append("%s: not pass" % k)
    shares = {k: {"share_of_rule_steps_with_a_lead": v.get("share_of_rule_steps_with_a_lead"), "n_rows": v.get("n_rows"), "n_lead_rows": v.get("n_lead_rows"),
                  "share_of_lead_steps_with_nonzero_closing": v.get("share_of_lead_steps_with_nonzero_closing")} for k, v in per.items()}
    return {"pass": not bad and bool(per), "failures": bad, "values": {"rollout_shares": shares}}


def _merge(**parts):
    """one control out of several: passes when every part passes; the failures of the parts in the order of their names"""
    out = {"pass": all(p.get("pass") is True for p in parts.values()) and bool(parts), "failures": [], "parts": sorted(parts)}
    vals, extra = {}, {}
    for k in sorted(parts):
        p = parts[k]
        out["failures"] += list(p.get("failures", []))
        if "values" in p:
            vals[k] = p["values"]
        e = {kk: vv for kk, vv in p.items() if kk not in ("pass", "failures", "values")}
        if e:
            extra[k] = e
    if vals:
        out["values"] = vals
    if extra:
        out["extra"] = extra
    return out


def compute_controls(a, m, wsha):
    """the ten controls j0 to j9 from the files on disk and the engine measures `m` ({"settings": {S: {levels, grid_all_pass, strategic_a, strategic_b}}}).
    j0 to j4: the record of the gap files; j5: wrapper and arguments (the model reader's controls on the wrapper and on the first line of each run log); j6: identity of the banked levels;
    j7: tests; j8: engine; j9: counts and rule logs (the done marker, the dump files, the rule log of each new run against its own gap file)."""
    c = {}
    gf = getattr(a, "gap_files", None) or {}
    shas = {nm: (sha_file(p) if p and os.path.isfile(p) else None) for nm, p in gf.items()}
    c.update(ctl_j01234(read_json(a.gap_record), shas))
    rshas = {"%s_%s_s%d" % (S, arm, mm): MD.run_file_sha(a.pull, run_name(S, arm), mm) for S, arm in new_pairs() for mm in SEEDS}
    present = bool(a.wrapper_check and os.path.isfile(a.wrapper_check) and a.wrapper_hashes and os.path.isfile(a.wrapper_hashes))
    e1 = ctl_e1(wsha, read_text(a.wrapper_check), read_text(a.wrapper_hashes), present, rshas)
    rc = rule_checks(a)
    lines = {"%s_%s_s%d" % (S, arm, mm): (read_text(run_text_path(a.pull, run_name(S, arm), mm)), read_text(run_text_path(a.pull, run_name(S, ref_arm(S, arm)), mm)))
             for S, arm in new_pairs() for mm in SEEDS}
    e2 = ctl_e2(lines, rc)
    c["j5"] = _merge(wrapper=e1, arguments=e2)
    c["j6"] = ctl_j6({S: (v or {}).get("levels") for S, v in (m.get("settings") or {}).items()})
    c["j7"] = ctl_e4(read_text(a.tests_queue), read_text(a.tests_read), a.tests_mtime_queue, a.tests_mtime_read, a.queue_start, a.controls_start)
    c["j8"] = ctl_e5(m.get("settings") or {})
    done, n_dumps = {}, {}
    for S, arm in new_pairs():
        for mm in SEEDS:
            k = "%s_%s_s%d" % (S, arm, mm)
            nm = run_name(S, arm)
            done[k] = os.path.isfile(os.path.join(run_folder(a.pull, nm, mm), "T1_DONE"))
            dd = os.path.join(run_folder(a.pull, nm, mm), "dump_I10%s_s%d_m10_causal_heads" % (nm, mm))
            n_dumps[k] = len([f for f in (os.listdir(dd) if os.path.isdir(dd) else []) if f.startswith("ep") and f.endswith(".npz")])
    e6 = ctl_e6(done, n_dumps, int(getattr(a, "expect_dumps", EXPECT_DUMPS)), read_text(a.done_marker) if getattr(a, "done_marker", "") else None)
    c["j9"] = _merge(counts=e6, rule_logs=ctl_e7(rc))
    return c


def assemble_controls(controls, payload, inputs):
    ok = sorted(controls) == sorted(CONTROLS) and all(isinstance(v, dict) and v.get("pass") is True for v in controls.values())
    vals = {k: v["values"] for k, v in controls.items() if isinstance(v, dict) and "values" in v}
    flat = {k: ({kk: vv for kk, vv in v.items() if kk != "values"} if isinstance(v, dict) else v) for k, v in controls.items()}
    pl = dict(payload)
    pl["control_values"] = vals
    res = {"card": CARD, "tier": TIER, "controls": flat, "all_pass": ok, "inputs": inputs}
    res["payload" if ok else "withheld"] = pl
    return res


# ============================================================================================ names (two separate derivations)
def _sg(iv):
    return -1 if iv[1] < 0.0 else (1 if iv[0] > 0.0 else 0)


def names_of(payload):
    """card section 4, written from the interval ends: per pair P of NAMED and measure M `BOXFUSE10K-<P>-LOWERS-<M>` (interval below 0), `-RAISES-<M>` (above 0), `-<M>-NOT-SEPARATED`; one summary
    name per pair: HELPS (lowers at least one, raises none), COSTS (raises at least one, lowers none), TRADES (lowers one and raises another), NOT-SEPARATED (none separated)."""
    out = {}
    for P, S, pk in NAMED:
        pr = payload["settings"][S]["pairs"][pk]
        lo, ra = [], []
        for mk, mw in MEASURES:
            iv = pr[mk]["interval"]
            if iv[1] < 0.0:
                out["%s_%s" % (P, mw)] = "%s-%s-LOWERS-%s" % (PRE, P, mw)
                lo.append(mw)
            elif iv[0] > 0.0:
                out["%s_%s" % (P, mw)] = "%s-%s-RAISES-%s" % (PRE, P, mw)
                ra.append(mw)
            else:
                out["%s_%s" % (P, mw)] = "%s-%s-%s-NOT-SEPARATED" % (PRE, P, mw)
        tail = "TRADES" if (lo and ra) else ("HELPS" if lo else ("COSTS" if ra else "NOT-SEPARATED"))
        out[P + "_SUMMARY"] = "%s-%s-JOINED-GAP-%s" % (PRE, P, tail)
    return out


def derive_all(payload):
    """independent second derivation of every name from the signs of the intervals (written apart from names_of, with the pairs and the words written out)"""
    out = {}
    word = {1: "RAISES-%s", -1: "LOWERS-%s"}
    for P, S, pk in (("K0-JEc", "K0", "JEc-VS-GEc"), ("CONV-JEc", "CONV", "JEc-VS-GEc"), ("K0-JA90", "K0", "JA90-VS-A90")):
        d = payload["settings"][S]["pairs"][pk]
        sg = []
        for mk, mw in (("U", "UNSAFE"), ("C", "CONTACT"), ("F", "FALLING-BEHIND")):
            s = _sg(d[mk]["interval"])
            sg.append(s)
            out["%s_%s" % (P, mw)] = "BOXFUSE10K-" + P + "-" + ((word[s] % mw) if s else (mw + "-NOT-SEPARATED"))
        key = (min(sg) < 0, max(sg) > 0)
        out[P + "_SUMMARY"] = "BOXFUSE10K-" + P + "-JOINED-GAP-" + {(True, True): "TRADES", (True, False): "HELPS", (False, True): "COSTS", (False, False): "NOT-SEPARATED"}[key]
    return out


def all_names(payload):
    got = names_of(payload)
    exp = derive_all(payload)
    diff = ["%s: got %s, expected %s" % (k, got.get(k), v) for k, v in sorted(exp.items()) if got.get(k) != v]
    diff += ["%s: name present that the card does not have" % k for k in sorted(got) if k not in exp]
    if diff:
        raise SystemExit("REFUSED: the names are not the ones the intervals give: %s" % diff)
    return got


def flat_names(names):
    return [names[k] for k in sorted(names)]


# ============================================================================================ the pod part (grid read and strategic read per setting)
def register_runs(S):
    spec = SPEC[S]
    for arm, r in spec["runs"].items():
        R.ALL_RUNS.setdefault(r, ("RLc" if arm in ("RLc", "PL") else "RR", spec["readout"], spec["P"], "deadreckon", spec["grid"], "plan", spec["every"], 0.2))
    R.ALL_RUNS.setdefault(SPREAD, ("R0", "pinned", 0, "deadreckon", "full", "plan", None, 0.2))


def measure_setting(a, E, S, keys, ctx_cache, log):
    """grid read of the runs of one setting (levels, pairs with intervals, families) and the strategic grid at T1-kin. Engine calls as in the model reader."""
    H = E[0]
    spec = SPEC[S]
    runs = spec["runs"]
    register_runs(S)
    pairs_def = {nm: (runs[x], runs[y]) for nm, (x, y) in PAIRS[S].items()}
    G = R.read_grid(a, E, spec["grid"], keys, [SPREAD] + sorted(set(runs.values())), SPREAD, pairs_def, {}, log)
    ok_levels = all(r in (G.get("levels") or {}) for r in runs.values())
    out = {"grid_all_pass": G["controls"].get("ALL_PASS") is True, "counts": G.get("counts") or {}, "levels": {}, "levels_per_seed": {}, "pairs": {}, "families": {}, "strategic": {"pairs": {}},
           "strategic_a": False, "strategic_b": False}
    if out["counts"]:
        out["instrument_bar_met"] = bool(out["counts"].get("n_lead_windows", 0) >= H.MIN_WINDOWS and out["counts"].get("n_episodes_with_lead", 0) >= H.MIN_EPISODES)
    if ok_levels:
        out["levels"] = {arm: {c: float(np.mean(G["levels"][r][c])) for c in ("C", "U", "F")} for arm, r in runs.items()}
        out["levels_per_seed"] = {arm: {c: [float(v) for v in np.asarray(G["levels"][r][c]).reshape(-1)[:2]] for c in ("C", "U", "F")} for arm, r in runs.items()}
    if G.get("pairs"):
        out["pairs"] = {nm: R.ucf(p["headway"]) for nm, p in G["pairs"].items()}
        out["families"] = {nm: {f_: R.reading(R.cells_of(p["family"]), f_) for f_ in R.NAMED} for nm, p in G["pairs"].items()}
    p_of = {"R0": 0}
    p_of.update({r: spec["P"] for r in runs.values()})
    try:
        SR, cells_s, eid_s, SS = R.strategic_grid(a, keys, sorted(p_of), p_of, log, ctx_cache)
    except SystemExit as ex:
        out["strategic_reason"] = "SystemExit: %s" % str(ex)[:200]
        return out
    except Exception as ex:                                                                   # noqa: BLE001
        out["strategic_reason"] = "%s: %s" % (type(ex).__name__, str(ex)[:200])
        return out
    sa, sb = bool(SR.get("stage_A_pass")), bool(SR.get("stage_B_pass"))
    out["strategic_a"], out["strategic_b"] = sa, sb
    out["strategic"]["controls"] = dict({k: v for k, v in SR["controls"].items() if k != "s3"}, s3=SR["controls"]["s3"].get("pass"))
    if sa and sb:
        for nm, (x, y) in STRAT_PAIRS[S].items():
            pr = SS.pair_read(cells_s, runs[x], runs[y], eid_s, ticks=(2,))
            pos = pr["tick2"]["pos"]
            out["strategic"]["pairs"][nm] = {"A": runs[x], "B": runs[y], "pos_30_50_80m_tick_t0_plus_20": [
                {"arc_m": arc, "mean": b["mean"], "lo": b["lo"], "hi": b["hi"], "verdict": b["verdict"], "n_per_seed": b.get("n_per_seed")} for arc, b in zip(SS.ARCS, pos)],
                "reading": R.family_of([c["verdict"] for c in pos])}
    else:
        out["strategic_reason"] = "the engine's strategic controls did not pass"
    return out


def grid_path(a, S):
    gf = SPEC[S]["grid_file"]
    return a.grid_pinned if gf == "pinned" else os.path.join(a.grid_dir, gf)


def measure(a, E, log):
    H = E[0]
    J = H.load_join()
    names_ = [str(c) for c in J["clip"]]
    ctx_cache = {}
    res = {}
    for S in SETTINGS:                                                                         # the same code path for the new cells and for the banked cells read as identity
        g = R.jl(grid_path(a, S))
        if g is None:
            res[S] = {"grid_all_pass": False, "levels": {}, "pairs": {}, "strategic_a": False, "strategic_b": False, "strategic_reason": "grid file %s cannot be read" % grid_path(a, S)}
            continue
        keys = R.grid_keys(g, names_)
        res[S] = measure_setting(a, E, S, keys, ctx_cache, log)
    return {"settings": res}


def input_files(a):
    """the files the controls stage reads, with their paths and sha256 (None for a file that is not there): the names stage hashes them again and refuses when one differs"""
    items = [("this_reader", os.path.abspath(__file__)), ("model_reader", MODEL_PATH), ("wrapper_file", getattr(a, "wrapper_file", "")), ("gap_record", a.gap_record),
             ("grid_pinned", getattr(a, "grid_pinned", "")), ("tests_queue", getattr(a, "tests_queue", "")), ("tests_read", getattr(a, "tests_read", ""))]
    items += [(nm, (getattr(a, "gap_files", None) or {}).get(nm)) for nm in sorted(NEW_FILES.values())]
    return {lab: {"path": os.path.abspath(p), "sha256": sha_file(p) if os.path.isfile(p) else None} for lab, p in items if p}


def inputs_changed(inputs):
    """-> the list of differences between the hashes the controls stage recorded and the files now; a record with no file hashes is a difference"""
    fl = (inputs or {}).get("files") if isinstance(inputs, dict) else None
    if not isinstance(fl, dict) or not fl:
        return ["the controls file records no input hashes"]
    bad = []
    for lab, v in sorted(fl.items()):
        p, want = (v or {}).get("path"), (v or {}).get("sha256")
        got = sha_file(p) if p and os.path.isfile(p) else None
        if got != want:
            bad.append("%s: sha256 %s now, %s at the controls stage" % (lab, (got or "none")[:16], (want or "none")[:16]))
    return bad


def run_controls(a):
    elog = a.out + ".engine.log"
    if os.path.exists(elog):
        raise SystemExit("REFUSED: %s exists" % elog)
    with io.open(elog, "w", encoding="utf-8", newline="\n") as fh, contextlib.redirect_stdout(fh):
        E = R.engine(a)
        m = measure(a, E, lambda s: print(s, flush=True))
    wsha = sha_file(a.wrapper_file)[:16] if a.wrapper_file and os.path.isfile(a.wrapper_file) else None
    controls = compute_controls(a, m, wsha)
    payload = {"settings": m["settings"], "family_note": FAM_NOTE}
    inputs = {"files": input_files(a), "wrapper_file_sha16": wsha}
    return assemble_controls(controls, payload, inputs)


def one_line(x, n=160):
    return " ".join(str(x).split())[:n]


def controls_lines(res):
    """the lines of the controls stage: `ctl j<k> PASS` or `ctl j<k> FAIL <first reason>` and the last line. No level, no difference and no name."""
    L = []
    for k in CONTROLS:
        c = (res.get("controls") or {}).get(k) or {}
        if c.get("pass") is True:
            L.append("ctl %s PASS" % k)
        else:
            L.append("ctl %s FAIL %s" % (k, one_line((c.get("failures") or ["not computed"])[0])))
    L.append("ZZ READ-BOXFUSE10K controls all_pass %s" % res.get("all_pass"))
    return L


def fmt_pair(p):
    return "; ".join("%s %s" % (label, json.dumps(p[mk], sort_keys=True, default=str)) for mk, label in MEASURES)


def print_sections(payload, names):
    L = ["TIER " + TIER]
    L += flat_names(names)
    for S in SETTINGS:
        d = payload["settings"][S]
        cn = d.get("counts") or {}
        L.append("setting %s (%s; grid %s): windows %s, windows with a lead %s, episodes with a lead %s, instrument bar of 200 windows and 20 episodes met %s" % (
            S, preroll_text(SPEC[S]["P"]), SPEC[S]["grid"], cn.get("n_windows"), cn.get("n_lead_windows"), cn.get("n_episodes_with_lead"), d.get("instrument_bar_met")))
        for arm in arms_of(S):
            lv = d["levels"][arm]
            L.append("level %s %s pooled C %.4f U %.4f F %.4f (windows with a lead %s); per model seed %s" % (S, arm, lv["C"], lv["U"], lv["F"], cn.get("n_lead_windows"),
                                                                                                          json.dumps((d.get("levels_per_seed") or {}).get(arm), sort_keys=True)))
        for nm in PAIRS[S]:
            L.append("%s %s: %s" % (S, nm, fmt_pair(d["pairs"][nm])))
        for nm in PAIRS[S]:
            st = (d.get("strategic") or {}).get("pairs", {}).get(nm)
            L.append("families %s %s: %s strategic %s" % (S, nm, json.dumps((d.get("families") or {}).get(nm) or {}, sort_keys=True),
                                                           st["reading"] if st else "not read (%s)" % d.get("strategic_reason", "no reason recorded")))
    cv = payload.get("control_values") or {}
    sh = ((cv.get("j9") or {}).get("rule_logs") or {}).get("rollout_shares") or {}
    for k in sorted(sh):
        L.append("rollout %s: %s" % (k, json.dumps(sh[k], sort_keys=True)))
    return L


LIMITS = ("Two model seeds; one detector with no training on our data; one fit of the locator in the rollouts (row 199 read three at T0); T1-kin reads recorded frames at the rollout's steps, "
          "there is no re-perception of what the rolled-out car would see; the rows the rule treats as a lead are those of the base file, so the presence input is unchanged by construction.")


def verdict_md(payload, names, controls_sha):
    """BOXFUSE10K_VERDICT.md: tier, controls, names, the four families, levels pooled and per model seed, pairs with intervals, the limits of card section 8"""
    L = ["# BOXFUSE10K verdict (card %s)" % CARD, "",
         "Tier: %s. A kinematic rollout on recorded frames, on the model's own actions; not driving performance." % TIER, "",
         "Controls: j0 to j9 all pass (controls file sha256 %s). This card has no map of arms to controls." % controls_sha[:16], "",
         "Estimator: two-level bootstrap over the two model seeds and the evaluation episodes, 2,000 draws, on the same windows for both arms of a pair. The interval answers what another draw of "
         "episodes and of these two model seeds would say, not what another training run, another detector or another fit of the locator would say.", "", "## Names", ""]
    L += ["- " + n for n in flat_names(names)]
    for S in SETTINGS:
        d = payload["settings"][S]
        cn = d.get("counts") or {}
        L += ["", "## Setting %s (%s)" % (S, preroll_text(SPEC[S]["P"])), "",
              "Windows with a lead %s, episodes with a lead %s." % (cn.get("n_lead_windows"), cn.get("n_episodes_with_lead")), "", "### Levels (contact C, unsafe U, falling behind F)", ""]
        for arm in arms_of(S):
            lv = d["levels"][arm]
            L.append("- %s pooled C %.4f U %.4f F %.4f; per model seed %s" % (arm, lv["C"], lv["U"], lv["F"], json.dumps((d.get("levels_per_seed") or {}).get(arm), sort_keys=True)))
        L += ["", "### Pairs (first minus second, with intervals)", ""]
        for nm in PAIRS[S]:
            L.append("- %s: %s" % (nm, fmt_pair(d["pairs"][nm])))
        L += ["", "### Families (longitudinal, lateral, tactical: engine reads of each pair; strategic: grid at T1-kin, position error at 30, 50 and 80 m)", ""]
        for nm in PAIRS[S]:
            st = (d.get("strategic") or {}).get("pairs", {}).get(nm)
            L.append("- %s: %s; strategic %s" % (nm, json.dumps((d.get("families") or {}).get(nm) or {}, sort_keys=True), st["reading"] if st else "not read (%s)" % d.get("strategic_reason", "no reason recorded")))
    L += ["", "## Limits (card section 8)", "", LIMITS, "", "The T0 reading of the card (BOXFUSE10K-T0 names) is not made by this reader.", "",
          "This card has no map of arms to controls.", ""]
    return "\n".join(L)


def main(argv=None):
    argv = sys.argv[1:] if argv is None else argv
    ap = argparse.ArgumentParser(allow_abbrev=False)
    ap.add_argument("--stage", choices=("controls", "names"))
    ap.add_argument("--selftest", action="store_true")
    for nme in ("pull", "code", "grid-dir", "grid-pinned", "w", "tree", "wrapper-file", "wrapper-check", "wrapper-hashes", "controls", "gap-record", "verdict",
                "eval-join", "tests-queue", "tests-read", "tests-mtime-queue", "tests-mtime-read", "queue-start", "controls-start", "done-marker", "model-reader"):
        ap.add_argument("--" + nme, default="")
    ap.add_argument("--gap-file", action="append", default=[])
    ap.add_argument("--out", default="")
    ap.add_argument("--log", default="")
    ap.add_argument("--n-boot", type=int, default=2000)
    ap.add_argument("--expect-dumps", type=int, default=EXPECT_DUMPS)
    a = ap.parse_args(argv)
    if a.selftest:
        print("REFUSED: this reader has no selftest; its tests are in test_boxfuse_read.py")
        return 2
    if not a.stage or not a.out:
        print("REFUSED: --stage and --out are required")
        return 2
    bind(a.model_reader)
    a.n_boot_control = 300
    if os.path.exists(a.out):
        print("REFUSED: %s exists" % a.out)
        return 2
    if a.stage == "controls":
        a.gap_record = a.gap_record or WS + "/boxfuse10k/gapfiles/BOXFUSE10K_GAPFILES_RECORD.json"
        a.gap_files = parse_gap_files(a.gap_file)
        for nm in sorted(NEW_FILES.values()):
            a.gap_files.setdefault(nm, WS + "/boxfuse10k/gapfiles/%s.npz" % nm)
        a.grid_pinned = a.grid_pinned or WS + "/hierrep/pins/" + PINNED_GRID_NAME
        a.tests_queue = a.tests_queue or WS + "/boxfuse10k/lead_tests/lead_pytest_queue.out"
        a.tests_read = a.tests_read or WS + "/boxfuse10k/lead_tests/lead_pytest_read.out"
        res = run_controls(a)
        io.open(a.out, "w", encoding="utf-8", newline="\n").write(json.dumps(res, indent=1, default=lambda o: float(o) if hasattr(o, "item") else str(o)))
        for ln in controls_lines(res):
            print(ln)
        return 0
    cj = read_json(a.controls) or {}
    if cj.get("card") != CARD or cj.get("all_pass") is not True or "payload" not in cj or sorted(cj.get("controls", {})) != sorted(CONTROLS) \
            or any((v or {}).get("pass") is not True for v in cj.get("controls", {}).values()):
        print("REFUSED: the controls file is not all-pass with j0 to j9 present: no name is written")
        print("ZZ READ-BOXFUSE10K names refused")
        return 3
    diff = inputs_changed(cj.get("inputs"))
    if diff:
        print("REFUSED: an input is not as the controls stage hashed it: %s" % one_line("; ".join(diff), 400))
        print("ZZ READ-BOXFUSE10K names refused")
        return 3
    logp = a.log or (os.path.splitext(a.out)[0] + "_names.log")
    vp = a.verdict or os.path.join(os.path.dirname(os.path.abspath(a.out)), PRE + "_VERDICT.md")
    for p in (logp, vp):
        if os.path.exists(p):
            print("REFUSED: %s exists" % p)
            return 2
    names = all_names(cj["payload"])
    csha = sha_file(a.controls)
    res = {"card": CARD, "tier": TIER, "controls_file": os.path.abspath(a.controls), "controls_sha256": csha, "names": names, "values": cj["payload"]}
    io.open(a.out, "w", encoding="utf-8", newline="\n").write(json.dumps(res, indent=1))
    io.open(vp, "w", encoding="utf-8", newline="\n").write(verdict_md(cj["payload"], names, csha))
    lines = print_sections(cj["payload"], names) + ["ZZ READ-BOXFUSE10K names done"]
    io.open(logp, "w", encoding="utf-8", newline="\n").write("\n".join(lines) + "\n")
    for ln in lines:
        print(ln)
    return 0


try:
    bind(os.environ.get("BOXFUSE_MODEL_READER", ""))
except ImportError as _ex:                      # bound again in main() from --model-reader; a missing one is reported there
    print("NOTE: %s" % _ex, file=sys.stderr)

if __name__ == "__main__":
    sys.exit(main())
